import{_ as i,c as o,a,o as n}from"./app-C_dHcy8Q.js";const t={};function c(r,e){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="deployment" tabindex="-1"><a class="header-anchor" href="#deployment"><span>Deployment</span></a></h1><ul><li>Server runs in DMZ/public with mTLS on :443 (configurable via --config or env CROUPIER_SERVER_*)</li><li>Agent runs in game private networks and dials out to Server (--config or env CROUPIER_AGENT_*)</li><li>Edge (optional) can be started with <code>croupier edge</code> to relay between Server and Agents</li><li>Game servers connect to local Agent</li></ul><p>Status: skeleton.</p><h2 id="geoip-ip2location-可选" tabindex="-1"><a class="header-anchor" href="#geoip-ip2location-可选"><span>GeoIP / IP2Location（可选）</span></a></h2><p>若希望在日志/审计/审批等页面展示“属地”（国家/省/市），可启用以下任一方案：</p><ol><li>离线库（推荐）</li></ol><ul><li>下载 IP2Location LITE DB（免费）： <ul><li>IPv4：IP2LOCATION-LITE-DB3.BIN</li><li>IPv6：IP2LOCATION-LITE-DB3.IPV6.BIN</li></ul></li><li>放置到 Server 工作目录的 <code>configs/</code> 下，文件名保持一致；或用环境变量显式指定： <ul><li>IP2LOCATION_BIN_PATH=/abs/path/IP2LOCATION-LITE-DB3.BIN</li><li>IP2LOCATION_BIN_PATH_V6=/abs/path/IP2LOCATION-LITE-DB3.IPV6.BIN</li></ul></li><li>Server 运行时会自动探测并启用；不存在时自动跳过。</li></ul><ol start="2"><li>在线 HTTP 解析</li></ol><ul><li>配置环境变量： <ul><li>GEOIP_HTTP_URL：例如 <code>https://your-geo.example.com/lookup?ip={{ip}}</code></li><li>GEOIP_TIMEOUT_MS：HTTP 调用超时，默认 1500</li></ul></li><li>响应 JSON 可包含 <code>country/country_name</code>、<code>region/region_name/province/state</code>、<code>city</code> 中的一种或多种字段。</li></ul><p>内网/本地地址不会进行查询：</p><ul><li>127.0.0.1/::1 → “本地”；10/172.16–31/192.168/169.254、fc00::/7、fe80::/10 → “局域网”。</li></ul><p>验证：</p><ul><li>登录后台后查看“登录日志”的“属地”列，或请求 <code>/api/audit?kinds=login</code> 查看 <code>meta.ip_region</code>。</li></ul>',13)])])}const d=i(t,[["render",c]]),s=JSON.parse('{"path":"/deployment.html","title":"Deployment","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1762592977000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":5,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"4edc9bbe294f0812cb6f9741c187cdb07ee16073","time":1762592977000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(geoip): document IP2Location LITE BIN external download and runtime enable; add configs/<em>.BIN to .gitignore\\\\n\\\\n- README: add GeoIP section with BIN download links, env vars, and behavior\\\\n- docs/deployment: add GeoIP/IP2Location setup guide\\\\n- .gitignore: ignore configs/</em>.BIN &#x26; .DS_Store"},{"hash":"fe3af0114d969a4312b6e7a9c66edb737e8f4003","time":1761964631000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs: reflect unified CLI (croupier server/agent/edge) and new env prefixes (CROUPIER_SERVER_<em>, CROUPIER_AGENT_</em>)"},{"hash":"4e71ba8fae83847ba983383b8ac02ce0a2e452c0","time":1761963778000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(config): add example YAMLs; README notes --config and CROUPIER_* env; deployment doc updated"},{"hash":"2850102635c30770039d04ddc769f91e4129703e","time":1761962609000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs: rename Core concept to Server across README and docs"},{"hash":"8e304eb04907065b7a86a2e28431a17d03e2e4e2","time":1761174667000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"feat(core,agent,ui): introduce gRPC+mTLS vNext skeleton with Core↔Agent↔SDK E2E, HTTP API, dynamic UI, jobs and RBAC\\\\n\\\\n- Protocol/IDL: add Function/Control proto (with dev stubs); buf configs\\\\n- Core: gRPC server, ControlService, FunctionService routing, HTTP API (/api/descriptors,/api/invoke,/api/start_job,/api/stream_job,/api/cancel_job)\\\\n- Agent: local FunctionService routing, LocalControlService for SDK registration, job executor with idempotency + cancel\\\\n- SDK: local handler hosting, schema validation, idempotency helper; example game server\\\\n- UI: static page with descriptor-driven form, invoke + start job + cancel, SSE progress\\\\n- Security: mTLS wiring, audit chain logger, basic RBAC (policy loader, HTTP enforcement)\\\\n- Tooling: Makefile, dev cert script, CI workflow, docs skeleton and descriptors"}]},"filePathRelative":"deployment.md"}');export{d as comp,s as data};
